yes(503,'D','Ammonium ions are weak acids: NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺. This makes NH₄Cl solution acidic. Sodium chloride is approximately neutral, while sodium carbonate is basic.',[ACID],question='Which aqueous solution is acidic, with pH below 7 at room temperature?',options=['Na₂SO₄(aq)','NaCl(aq)','Na₂CO₃(aq)','NH₄Cl(aq)'])
yes(504,'C','NaOH dissociates to give [OH⁻] ≈ 2.50 × 10⁻⁵ mol dm⁻³. Therefore pOH = −log₁₀(2.50 × 10⁻⁵) = 4.60. At 25 °C, pH = 14.00 − 4.60 = 9.40.',[ACID],question='What is the pH of a 2.50 × 10⁻⁵ mol dm⁻³ NaOH solution at 25 °C?',options=['3.6','5.0','9.4','12.0'],audit='Corrected old D to C by independent logarithm and full water-ionisation quadratic. Stated standard25°C convention; removed next-graph text from D.',check='naoh-ph')
